from pymongo import MongoClient, ASCENDING
from pymongo.errors import DuplicateKeyError

MONGODB_URI = os.environ.get("MONGODB_URI", "").strip()
MONGODB_DB = os.environ.get("MONGODB_DB", "fairlane_coffee_house").strip() or "fairlane_coffee_house"

@st.cache_resource
def get_mongo_db():
    if not MONGODB_URI:
        raise RuntimeError("MONGODB_URI is not configured. Add it to your environment or Streamlit secrets.")
    client = MongoClient(MONGODB_URI, serverSelectionTimeoutMS=5000)
    client.admin.command("ping")
    return client[MONGODB_DB]

def ensure_mongo_database():
    db = get_mongo_db()
    db.customers.create_index([("email", ASCENDING)], unique=True)
    db.orders.create_index([("order_number", ASCENDING)], sparse=True)
    db.reservations.create_index([("reservation_id", ASCENDING)], unique=True)
    db.employees.create_index([("employee_id", ASCENDING)], unique=True)
    db.employee_credentials.create_index([("email", ASCENDING)], unique=True)
    db.employee_credentials.create_index([("employee_id", ASCENDING)], unique=True)
    db.attendance.create_index([("employee_id", ASCENDING), ("date", ASCENDING)], unique=True)
    return db

def _next_prefixed_id(collection, field, prefix, width):
    latest = collection.find_one({field: {"$regex": f"^{prefix}\\d+$"}}, sort=[(field, -1)])
    highest = 0
    if latest:
        value = str(latest.get(field, ""))
        if value.startswith(prefix) and value[len(prefix):].isdigit():
            highest = int(value[len(prefix):])
    return f"{prefix}{highest + 1:0{width}d}"

def get_saved_reservations():
    db = ensure_mongo_database()
    rows = []
    for item in db.reservations.find({}, {"_id": 0}).sort("booked_at", ASCENDING):
        rows.append({
            "reservation_id": str(item.get("reservation_id") or ""), "name": str(item.get("guest_name") or ""),
            "email": str(item.get("guest_email") or ""), "date": str(item.get("date") or ""),
            "time": str(item.get("time") or ""), "time_24": str(item.get("time_24") or ""),
            "guests": int(item.get("guests") or 0), "table_id": str(item.get("table_id") or ""),
            "seating": str(item.get("seating") or ""), "capacity": int(item.get("capacity") or 0),
            "notes": str(item.get("special_request") or ""), "status": str(item.get("status") or "Confirmed")})
    return rows

def save_reservation_to_excel(reservation):
    db = ensure_mongo_database()
    for _ in range(5):
        reservation_id = _next_prefixed_id(db.reservations, "reservation_id", "R", 5)
        doc = {"reservation_id": reservation_id, "guest_name": reservation["name"], "guest_email": reservation["email"],
               "date": reservation["date"], "time": reservation["time"], "time_24": reservation["time_24"],
               "guests": int(reservation["guests"]), "table_id": reservation["table_id"], "seating": reservation["seating"],
               "capacity": int(reservation["capacity"]), "special_request": reservation.get("notes", ""),
               "status": "Confirmed", "booked_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "email_status": "Pending"}
        try: db.reservations.insert_one(doc); return reservation_id
        except DuplicateKeyError: continue
    raise RuntimeError("Could not generate a unique reservation ID.")

