def hash_password(password, salt=None):
    if salt is None: salt = secrets.token_hex(16)
    password_hash = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), 120000).hex()
    return salt, password_hash

def _load_orders_for_email(email):
    db = ensure_mongo_database(); results=[]
    for record in db.orders.find({"email": email.strip().lower()}, {"_id": 0}).sort("date", ASCENDING):
        items = record.get("items", [])
        if isinstance(items, str): items = [x.strip() for x in items.split(",") if x.strip()]
        results.append({"number": record.get("order_number"), "items": items, "total": float(record.get("total") or 0),
                        "pickup": record.get("pickup") or "", "payment": record.get("payment") or "", "date": record.get("date") or ""})
    return results

def get_user_from_excel(email):
    db=ensure_mongo_database(); email=email.strip().lower(); customer=db.customers.find_one({"email": email}, {"_id":0})
    if not customer: return None
    account=dict(customer); account["order_history"]=json.dumps(_load_orders_for_email(email))
    account["favorites"]=json.dumps(customer.get("favorites", [])); account["saved_deals"]=json.dumps(customer.get("saved_deals", []))
    account["cart"]=json.dumps(customer.get("cart", [])); account["last_order"]=json.dumps(customer.get("last_order")) if customer.get("last_order") else ""
    return account

def verify_login(email, password):
    account=get_user_from_excel(email)
    if not account: return None
    salt=account.get("password_salt") or ""; stored_hash=account.get("password_hash") or ""
    if not salt or not stored_hash: return None
    return account if hash_password(password, salt)[1] == stored_hash else None

def create_user_in_excel(name, email, password):
    db=ensure_mongo_database(); email=email.strip().lower()
    if db.customers.find_one({"email":email}): return False
    salt,password_hash=hash_password(password)
    doc={"customer_id":_next_prefixed_id(db.customers,"customer_id","C",3), "name":name.strip(), "email":email, "phone":"",
         "reward_points":0, "favorite_drink":"Fairlane Focus", "milk":"Oat Milk", "visit_goal":"Focus", "dietary":"No Preference",
         "temperature":"Cold", "joined_date":datetime.now().strftime("%Y-%m-%d"), "password_salt":salt, "password_hash":password_hash,
         "favorites":[], "saved_deals":[], "cart":[], "email_deals":True, "personalized_recommendations":True, "order_updates":True, "last_order":None}
    try: db.customers.insert_one(doc); return True
    except DuplicateKeyError: return False

def reset_customer_password(email, new_password):
    db=ensure_mongo_database(); email=email.strip().lower()
    if not db.customers.find_one({"email":email}): return False
    salt,password_hash=hash_password(new_password)
    return db.customers.update_one({"email":email},{"$set":{"password_salt":salt,"password_hash":password_hash}}).modified_count > 0

def load_account_into_session(account):
    if not isinstance(account, dict): return False
    st.session_state.customer_profile={"name":account.get("name") or "", "email":account.get("email") or "", "phone":account.get("phone") or "",
        "favorite_drink":account.get("favorite_drink") or "Fairlane Focus", "milk":account.get("milk") or "Oat Milk",
        "visit_goal":account.get("visit_goal") or "Focus", "dietary":account.get("dietary") or "No Preference", "temperature":account.get("temperature") or "Cold"}
    st.session_state.favorites=json.loads(account.get("favorites") or "[]"); st.session_state.saved_deals=json.loads(account.get("saved_deals") or "[]")
    st.session_state.reward_points=int(account.get("reward_points") or 0); st.session_state.order_history=json.loads(account.get("order_history") or "[]")
    last_order=account.get("last_order"); st.session_state.last_order=json.loads(last_order) if last_order else None
    st.session_state.cart=json.loads(account.get("cart") or "[]"); st.session_state.email_deals=bool(account.get("email_deals",True))
    st.session_state.personalized_recommendations=bool(account.get("personalized_recommendations",True)); st.session_state.order_updates=bool(account.get("order_updates",True))
    st.session_state.logged_in_email=str(account.get("email") or "").lower(); return True

def save_current_user_to_excel():
    if not st.session_state.get("signed_in") or not st.session_state.get("logged_in_email"): return
    db=ensure_mongo_database(); old_email=st.session_state.logged_in_email.strip().lower(); profile=st.session_state.customer_profile
    new_email=profile.get("email","").strip().lower() or old_email
    updates={"name":profile.get("name",""), "email":new_email, "phone":profile.get("phone",""), "reward_points":int(st.session_state.reward_points),
        "favorite_drink":profile.get("favorite_drink","Fairlane Focus"), "milk":profile.get("milk","Oat Milk"), "visit_goal":profile.get("visit_goal","Focus"),
        "dietary":profile.get("dietary","No Preference"), "temperature":profile.get("temperature","Cold"), "favorites":list(st.session_state.favorites),
        "saved_deals":list(st.session_state.saved_deals), "cart":list(st.session_state.cart), "email_deals":st.session_state.email_deals,
        "personalized_recommendations":st.session_state.personalized_recommendations, "order_updates":st.session_state.order_updates, "last_order":st.session_state.last_order}
    db.customers.update_one({"email":old_email},{"$set":updates});
    if new_email != old_email: db.orders.update_many({"email":old_email},{"$set":{"email":new_email}})
    st.session_state.logged_in_email=new_email

