    if existing: return existing
    defaults=[{"name":"Ava","role":"Shift Lead","shift":"7 AM - 3 PM","attendance":98,"performance":95},
              {"name":"Noah","role":"Barista","shift":"8 AM - 4 PM","attendance":96,"performance":92},
              {"name":"Mia","role":"Barista","shift":"12 PM - 8 PM","attendance":94,"performance":90},
              {"name":"Liam","role":"Cashier","shift":"2 PM - 10 PM","attendance":97,"performance":91}]
    for e in defaults: save_employee_to_excel(e)
