def get_price(item_name):
    """Return a price safely for current and legacy cart entries."""
    if isinstance(item_name, dict):
        direct_price = item_name.get("price")
        item_name = item_name.get("name", "")
        if isinstance(direct_price, (int, float)) and item_name not in menu and item_name not in deals:
            return float(direct_price)

    if not isinstance(item_name, str):
        item_name = str(item_name)

    if item_name in menu:
        return menu[item_name]["price"]

    if item_name in deals:
        return deals[item_name]["price"]

    interactive_deal_prices = {
        "Focus Combo": 6.49,
        "Student Deal": 5.99,
        "Waste-Saver Deal": 5.25,
        "Coffee Together Deal": 14.99,
        "AI Focus Bundle": 6.25,
    }
    if item_name in interactive_deal_prices:
        return interactive_deal_prices[item_name]

    return 5.50

def add_to_cart(item_name):
    st.session_state.cart.append(item_name)
    save_current_user_to_excel()

def add_favorite(item_name):
    if item_name not in st.session_state.favorites:
        st.session_state.favorites.append(item_name)
        save_current_user_to_excel()

def save_deal(deal_name):
    if deal_name not in st.session_state.saved_deals:
        st.session_state.saved_deals.append(deal_name)
        save_current_user_to_excel()

def update_live_data():
    """Simulate changing café conditions while Fairlane is open."""
    st.session_state.live_wait = max(
        2,
        min(20, int(st.session_state.get("live_wait", 5)) + random.randint(-2, 2))
    )

    st.session_state.available_seats = max(
        0,
        min(40, int(st.session_state.get("available_seats", 20)) + random.randint(-3, 3))
    )

    total_seats = 40
    occupied_seats = total_seats - st.session_state.available_seats
    st.session_state.occupancy = round((occupied_seats / total_seats) * 100)

    st.session_state.customer_satisfaction = max(
        85,
        min(100, int(st.session_state.get("customer_satisfaction", 94)) + random.randint(-1, 1))
    )

def reset_live_data_for_closed_store():
    """Reset operational values whenever the coffee house is closed."""
    st.session_state.live_wait = 0
    st.session_state.available_seats = 40
    st.session_state.occupancy = 0

def initialize_live_data_for_open_store():
    """Start a fresh live simulation when Fairlane reopens."""
    st.session_state.live_wait = random.randint(2, 6)
    st.session_state.available_seats = random.randint(18, 32)

    total_seats = 40
    occupied_seats = total_seats - st.session_state.available_seats
    st.session_state.occupancy = round((occupied_seats / total_seats) * 100)

def get_business_store_status(business_hours, now=None):
    """Return OPEN/CLOSED using the current local machine time and today's hours."""
    now = now or datetime.now()
    day_name = now.strftime("%A")
    opening, closing = business_hours[day_name]

    open_time = datetime.strptime(opening, "%I:%M %p")
    close_time = datetime.strptime(closing, "%I:%M %p")

    current_minutes = now.hour * 60 + now.minute
    open_minutes = open_time.hour * 60 + open_time.minute
    close_minutes = close_time.hour * 60 + close_time.minute

    return "OPEN" if open_minutes <= current_minutes <= close_minutes else "CLOSED"

@st.fragment(run_every="5s")
def render_home_live_metrics():
    update_live_data()

    c1, c2, c3, c4 = st.columns(4)

    c1.metric(
        "Current Wait",
        f"{st.session_state.live_wait} min"
    )
    c2.metric(
        "Available Seats",
        st.session_state.available_seats
    )
    c3.metric(
        "Today's Deals",
        len(deals)
    )
    c4.metric(
        "Customer Satisfaction",
        f"{st.session_state.customer_satisfaction}%"
    )

    st.caption("Live simulation updates automatically every 5 seconds.")

