@st.fragment(run_every="5s")
def render_business_live_metrics(business_hours):
    """Reference-image Business Operations cards with dynamic live values."""
    store_status = get_business_store_status(business_hours)
    previous_status = st.session_state.get("business_store_status")

    if store_status == "CLOSED":
        reset_live_data_for_closed_store()
    elif previous_status != "OPEN":
        initialize_live_data_for_open_store()
    else:
        update_live_data()

    st.session_state.business_store_status = store_status

    occupancy = max(0, min(100, int(st.session_state.get("occupancy", 0))))
    wait = max(0, int(st.session_state.get("live_wait", 0)))
    seats = max(0, min(40, int(st.session_state.get("available_seats", 40))))

    if store_status == "CLOSED":
        occupancy, wait, seats = 0, 0, 40
        status_note = "Currently closed"
        wait_note = "Resets while closed"
        occupancy_note = "No café activity"
        seats_note = "All seats available"
    else:
        status_note = "Serving with a smile!"
        wait_note = "Average wait time"
        occupancy_note = "Low café activity" if occupancy < 35 else ("Moderate café activity" if occupancy < 70 else "Busy café activity")
        seats_note = "Seats ready for you"

    status_class = "open" if store_status == "OPEN" else "closed"

