# FLOATING CUSTOMER AI ASSISTANT
# ==================================================
CUSTOMER_ASSISTANT_HOURS = {
    "Monday": ("07:00 AM", "07:00 PM"), "Tuesday": ("07:00 AM", "07:00 PM"),
    "Wednesday": ("07:00 AM", "05:00 PM"), "Thursday": ("07:00 AM", "07:00 PM"),
    "Friday": ("07:00 AM", "10:00 PM"), "Saturday": ("10:00 AM", "10:00 PM"),
    "Sunday": ("10:00 AM", "10:00 PM")
}

def customer_ai_reply(prompt):
    """Customer-safe assistant using customer-facing Fairlane data only."""
    q = str(prompt or "").strip().lower()
    if not q:
        return "Ask me about Fairlane’s menu, deals, wait time, seating, rewards, or your order."
    if any(x in q for x in ["hello", "hi", "hey"]):
        name = st.session_state.customer_profile.get("name", "") if st.session_state.get("signed_in") else ""
        return f"Hi{', ' + name if name else ''}! ☕ How can I help with your Fairlane visit today?"
    if any(x in q for x in ["recommend", "suggest", "what should i drink", "drink for me", "favorite"]):
        profile = st.session_state.get("customer_profile", {})
        if st.session_state.get("signed_in"):
            return f"Based on your profile, I’d start with **{profile.get('favorite_drink', 'Fairlane Focus')}**. Your saved preference is **{profile.get('temperature', 'Cold')}** and your visit goal is **{profile.get('visit_goal', 'Focus')}**."
        return "For focus, try **Fairlane Focus**. For something bold, try **Dearborn Midnight**. For a smooth cold option, try **Cold Brew Cloud**. For a calmer non-coffee choice, try **Matcha Reset**."
    if any(x in q for x in ["menu", "drink list", "food", "coffee", "tea"]):
        lines = [f"**{name}** — ${data['price']:.2f} · {data['description']}" for name, data in menu.items()]
        return "### Fairlane Menu\n\n" + "\n\n".join(lines)
    if any(x in q for x in ["deal", "offer", "discount", "combo", "special"]):
        lines = [f"**{name}** — ${data['price']:.2f} · {data['description']}" for name, data in deals.items()]
        return "### Today’s Deals\n\n" + "\n\n".join(lines)
    if any(x in q for x in ["open", "close", "hour", "hours"]):
        now = datetime.now(); day = now.strftime("%A")
        opening, closing = CUSTOMER_ASSISTANT_HOURS[day]
        status = get_business_store_status(CUSTOMER_ASSISTANT_HOURS, now)
        return f"Fairlane is **{status}** right now. Today ({day}) the coffee house is scheduled for **{opening} – {closing}**."
    if any(x in q for x in ["wait", "busy", "occupancy", "seat", "seating", "crowd"]):
        return f"Current café snapshot: **{int(st.session_state.get('live_wait', 0))} min wait**, **{int(st.session_state.get('available_seats', 0))} seats available**, and about **{int(st.session_state.get('occupancy', 0))}% occupancy**."
    if any(x in q for x in ["cart", "basket", "current order", "what did i add"]):
        cart = st.session_state.get("cart", [])
        if not cart: return "Your current order is empty. I can show the menu or today’s deals to help you choose."
        names = [item.get("name", "Item") if isinstance(item, dict) else str(item) for item in cart]
        subtotal = sum(get_price(item) for item in cart)
        return f"You have **{len(cart)} item(s)**: {', '.join(names)}. Estimated subtotal: **${subtotal:.2f}** before tax."
    if any(x in q for x in ["reward", "points", "loyalty"]):
        if not st.session_state.get("signed_in"): return "Sign in to Customer Portal and I can show your Fairlane reward points."
        return f"You currently have **{int(st.session_state.get('reward_points', 0))} Fairlane reward points**."
    if any(x in q for x in ["last order", "order status", "my order", "order history"]):
        last = st.session_state.get("last_order")
        if not last: return "I don’t see a recent order in this session. You can place an order from Menu & Deals or review your account in Customer Portal."
        return f"Your latest order is **#{last.get('number', '')}** for **${float(last.get('total', 0)):.2f}**, with pickup set to **{last.get('pickup', 'ASAP')}**."
    if any(x in q for x in ["vegan", "diet", "dietary", "allergy", "allergies", "milk", "oat"]):
        return "I can help narrow choices by preference, but this app does not contain a complete ingredient/allergen database. For allergies, please confirm ingredients with Fairlane staff before ordering."
    if any(x in q for x in ["contact", "support", "problem", "issue"]):
        return "For a message to the café team, use **Business Operations → Contact Fairlane**. I can also help here with menu, deals, orders, rewards, wait time, and seating."
    return "I can help with **menu & prices, deals, drink recommendations, store hours, wait time, seating, your cart, rewards, and recent orders**. Try “What do you recommend?”"

