    with order_tab:
        st.markdown(
            '<div class="menu-heading-wrap"><div class="menu-title">My Order</div>'
            '<div class="menu-subtitle">Review your items and choose pickup and payment.</div></div>',
            unsafe_allow_html=True,
        )

        if not st.session_state.cart:
            st.info("Your order is empty. Add something from the Menu or Deals tab.")
        else:
            subtotal = 0

            # Convert stale cart dictionaries from older app versions to names.
            normalized_cart = []
            for cart_entry in st.session_state.cart:
                if isinstance(cart_entry, dict):
                    cart_entry = cart_entry.get("name", "")
                if cart_entry:
                    normalized_cart.append(str(cart_entry))
            st.session_state.cart = normalized_cart

            for index, item in enumerate(st.session_state.cart):
                price = get_price(item)
                with st.container(border=True):
                    c1, c2, c3 = st.columns(
                        [4.6, 1, .9],
                        gap="small",
                        vertical_alignment="center",
                    )
                    c1.markdown(f"**{item}**")
                    c2.markdown(f"**${price:.2f}**")
                    if c3.button(
                        "Remove",
                        key=f"order_remove_{index}",
                        use_container_width=True,
                    ):
                        st.session_state.cart.pop(index)
                        st.rerun()
                subtotal += price

            st.divider()
            tax = subtotal * 0.06
            total = subtotal + tax

            t1, t2, t3 = st.columns(3)
            t1.metric("Subtotal", f"${subtotal:.2f}")
            t2.metric("Tax", f"${tax:.2f}")
            t3.metric("Total", f"${total:.2f}")

            pickup = st.selectbox(
                "Pickup Time",
                ["ASAP", "15 Minutes", "30 Minutes", "45 Minutes"],
                key="main_order_pickup",
            )

            payment = st.selectbox(
                "Payment Method",
                ["Credit / Debit Card", "Apple Pay", "Google Pay", "Pay at Counter"],
                key="main_order_payment",
            )

            reusable = st.checkbox(
                "♻️ I will bring a reusable cup",
                key="main_order_reusable",
            )

            if st.button(
                "✅ Place Order",
                use_container_width=True,
                type="primary",
                key="main_place_order",
            ):
                order_number = random.randint(1000, 9999)
                new_order = {
                    "number": order_number,
                    "items": st.session_state.cart.copy(),
                    "total": total,
                    "pickup": pickup,
                    "payment": payment,
                    "date": datetime.now().strftime("%b %d, %Y - %I:%M %p"),
                }

                st.session_state.last_order = new_order
                save_order_to_excel(new_order, reusable)

                points_earned = 0
                if st.session_state.signed_in:
                    st.session_state.order_history.append(new_order)
                    points_earned = int(total * 10)
                    st.session_state.reward_points += points_earned
                    save_current_customer()

                st.session_state.cart = []

                st.success(
                    f"✅ Order #{order_number} confirmed! Total: **${total:.2f}** • Pickup: **{pickup}**"
                )

                if points_earned > 0:
                    st.info(f"🎁 You earned **{points_earned} reward points** from this order.")

                if reusable:
                    st.info("♻️ Thanks for helping reduce disposable-cup waste.")

                st.rerun()


