with st.popover("☕ Ask Fairlane AI", key="customer_ai_floating_popover", use_container_width=False):
    st.markdown("### ☕ Fairlane AI Assistant")
    st.caption("Customer assistant · Menu · Deals · Orders · Rewards · Café info")
    for message in st.session_state.customer_ai_messages[-6:]:
        with st.chat_message(message.get("role", "assistant")):
            st.markdown(message.get("content", ""))

    qa1, qa2 = st.columns(2)
    quick_customer_prompt = None
    if qa1.button("✨ Recommend", key="customer_ai_recommend", use_container_width=True): quick_customer_prompt = "What do you recommend for me?"
    if qa2.button("🏷️ Deals", key="customer_ai_deals", use_container_width=True): quick_customer_prompt = "What deals are available?"
    qa3, qa4 = st.columns(2)
    if qa3.button("🪑 Seats & Wait", key="customer_ai_wait", use_container_width=True): quick_customer_prompt = "What is the wait time and seating availability?"
    if qa4.button("🛒 My Order", key="customer_ai_order", use_container_width=True): quick_customer_prompt = "What is in my current order?"

    with st.form("customer_ai_form", clear_on_submit=True):
        customer_question = st.text_input("Ask", placeholder="Ask about drinks, deals, hours, rewards...", label_visibility="collapsed")
        customer_send = st.form_submit_button("Send", use_container_width=True, type="primary")

    prompt_to_answer = quick_customer_prompt or (customer_question.strip() if customer_send else "")
    if prompt_to_answer:
        st.session_state.customer_ai_messages.append({"role":"user", "content":prompt_to_answer})
        st.session_state.customer_ai_messages.append({"role":"assistant", "content":customer_ai_reply(prompt_to_answer)})
        st.rerun()

    if st.button("Clear chat", key="customer_ai_clear", use_container_width=True):
        st.session_state.customer_ai_messages = [{"role":"assistant", "content":"Hi! I’m Fairlane AI ☕ How can I help with your visit today?"}]
        st.rerun()
